-- 024: the empty faction lists of spawned NPCs, filled from Quarm.
--
-- 2116 npc_faction rows of the dump had no primary faction and no entry (the Bashers of Grobb, merchants,
-- guards, guild masters...): their NPCs conned indifferent to everybody, never helped a player they should like,
-- and killing them moved no faction. Each takes the primary faction and the entries (6929 in all) of the Quarm NPC
-- of the same zone and name; factions are matched by name. Generated by tools/npc_stats/gen_npc_factions.py
-- (regenerate rather than edit; generate before applying: it reads the live tables).
-- 33 lists whose NPCs have different lists in Quarm are left as they were.
--
-- The rows changed are kept in npc_faction_before_024. To restore: delete the npc_faction_entries rows of those
-- lists and put the npc_faction rows back. Idempotent.

CREATE TABLE IF NOT EXISTS npc_faction_before_024 LIKE npc_faction;

